const supported=Object.keys(translations);const path=location.pathname;const first=path.split('/').filter(Boolean)[0];const lang=supported.includes(first)?first:'en';const t=translations[lang];document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t[el.dataset.i18n]||el.textContent);document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t[el.dataset.i18nPlaceholder]||el.placeholder);document.title=`Joyagooocom | ${t.spreadsheetTitle}`;document.getElementById('language').value=lang;
const suffix=path.replace(new RegExp('^/'+lang),'')||'/';document.getElementById('language').addEventListener('change',e=>location.href='/'+e.target.value+suffix);document.querySelectorAll('a[data-route]').forEach(a=>{a.href='/'+lang+({home:'/',categories:'/product-categories/',details:'/product-details/',seo:'/seo-articles/',faq:'/faq/',spreadsheet:'/spreadsheet/',buy:'/how-to-buy/',news:'/news/'}[a.dataset.route]);});document.getElementById('guideLink').href='/'+lang+'/how-to-buy/';document.getElementById('spreadsheetLink').href='/'+lang+'/spreadsheet/';document.getElementById('buyLink').href='/'+lang+'/how-to-buy/';document.getElementById('faqLink').href='/'+lang+'/faq/';
